// Visual operator-console views. They only render values reported by the
// Control Plane and its agents; unavailable telemetry stays explicitly blank.
const bytes=value=>value==null?'—':`${(Number(value)/1024/1024/1024).toFixed(1)} GB`,pct=value=>value==null?0:Math.max(0,Math.min(100,Number(value)));
function gauge(label,value,detail,tone='cyan'){const amount=pct(value);return `<article class="telemetry-gauge ${tone}" style="--value:${amount}%"><div><b>${value==null?'—':`${amount.toFixed(amount%1?1:0)}%`}</b><small>${esc(label)}</small></div><span>${esc(detail||'Awaiting agent telemetry')}</span></article>`}
function executionRows(values,empty){return values?.length?values.map(x=>{const total=Number(x.total||0),failed=Number(x.failed||0),rate=total?Math.round((total-failed)*100/total):100;return `<div class="execution-row"><div><b>${esc(x.name)}</b><small>${total} completed or failed events</small></div><div class="progress"><i style="--value:${rate}%"></i></div><span>${x.completed||0} ok</span><span class="${failed?'fault':''}">${failed||0} failed</span></div>`}).join(''):`<div class="empty">${esc(empty)}</div>`}
function renderDataPlanes(){const online=state.dataPlanes.filter(x=>x.status==='ONLINE').length,capacity=state.dataPlanes.reduce((n,x)=>n+Number(x.capacity||0),0),apps=state.dataPlanes.reduce((n,x)=>n+Number(x.applicationCount||0),0);setStats([metric(`${online}/${state.dataPlanes.length}`,'MACHINES ONLINE'),metric(capacity,'TOTAL CAPACITY'),metric(apps,'DEPLOYED APPLICATIONS'),metric(state.capabilities.filter(x=>x.health==='RUNNING').length,'RUNTIMES HEALTHY')]);action('Add machine / data plane',()=>q('#dataPlaneDialog').showModal());const cards=state.dataPlanes.map(x=>{const t=x.telemetry?.system||x;return `<article class="card machine-card"><div class="card-head"><div><small>${esc(x.type).toUpperCase()} · ${esc(x.region)}</small><b>${esc(x.name)}</b><small>${esc(x.host||x.id)}</small></div>${status(x.status)}</div><div class="machine-gauges"><span><i style="--value:${pct(t.cpuPercent)}%"></i>CPU <b>${t.cpuPercent??'—'}%</b></span><span><i style="--value:${pct(t.memoryPercent)}%"></i>RAM <b>${t.memoryPercent??'—'}%</b></span></div><div class="machine-facts"><span>${x.capabilityCount||0}<small>CAPABILITIES</small></span><span>${x.applicationCount||0}<small>APPS</small></span><span>${t.processCount??'—'}<small>WORKERS</small></span></div><small class="heartbeat">Heartbeat ${fmt(x.lastHeartbeat)}</small><div class="actions"><button onclick="dataPlaneDetails('${esc(x.id)}')">Inspect</button><button onclick="editDataPlane('${esc(x.id)}')">Configure</button></div></article>`}).join('')||'<div class="empty">No machines are registered. Add a data plane, then start its remote agent to establish the tunnel.</div>';q('#content').innerHTML=panel('Machine network','Register and operate the hosts that run MINA workloads',`<div class="network-summary"><span class="network-node control">CONTROL<br>PLANE</span><i></i><span class="network-label">Authenticated agent heartbeats</span><i></i><span class="network-node runtime">${online} ONLINE<br>RUNTIMES</span></div><div class="cards machine-grid">${cards}</div>`)}
function renderObservability(){const o=state.observability||{},s=o.summary||{},planes=o.dataPlanes||[];setStats([metric(s.applications||0,'PROJECTS'),metric(s.runningInstances||0,'RUNTIME WORKERS'),metric(s.requestCount||0,'CONTROL-PLANE REQUESTS'),metric(`${s.errorRate||0}%`,'CONTROL-PLANE ERROR RATE')]);noAction();const hosts=planes.map(x=>{const t=x.telemetry?.system||x;return `<article class="host-telemetry"><div class="card-head"><div><small>${esc(x.id)}</small><b>${esc(x.name)}</b></div>${status(x.status)}</div><div class="gauge-grid">${gauge('CPU',t.cpuPercent,`Load ${t.loadAverage??'—'}`)}${gauge('RAM',t.memoryPercent,`${bytes(t.memoryUsedBytes)} / ${bytes(t.memoryTotalBytes)}`,'green')}${gauge('Disk',t.diskPercent,`${bytes(t.diskFreeBytes)} free`,'amber')}</div><div class="host-footer"><span>${t.processCount??'—'} workers</span><span>Heartbeat ${fmt(x.lastHeartbeat)}</span></div></article>`}).join('')||'<div class="empty">No agent telemetry yet. Start the remote data-plane agent and wait for its next heartbeat.</div>';q('#content').innerHTML=panel('Host telemetry','Live CPU, RAM, disk, load, and worker counts sent by remote data-plane agents',`<div class="host-telemetry-grid">${hosts}</div>`)+panel('Execution analytics','Task and activity outcomes collected from runtime JSON logs on each data plane',`<div class="execution-columns"><div><h3>Tasks</h3>${executionRows(state.operatorMetrics?.tasks,'No completed task events have been reported yet.')}</div><div><h3>Activities</h3>${executionRows(state.operatorMetrics?.activities,'No completed activity events have been reported yet.')}</div></div>`)+panel('Control-plane request activity','Top API routes since the current Control Plane process started',`<div class="bars">${Object.entries(o.requests?.routes||{}).sort((a,b)=>b[1]-a[1]).slice(0,10).map(([name,count])=>`<div class="bar"><span>${esc(name)}</span><i style="--value:${Math.min(100,Number(count))}%"></i><b>${count}</b></div>`).join('')||'<div class="empty">No request telemetry is available for this account.</div>'}</div>`)}
const baseLoad=load;load=async function(){await baseLoad();try{state.operatorMetrics=await api('/api/operator/metrics');if(state.view==='observability')renderObservability()}catch(error){console.warn('Operator metrics unavailable',error)}};
const state={view:'home',health:{},session:{},overview:{},dataPlanes:[],capabilities:[],applications:[],deployments:[],resources:[],teams:[],principals:[],observability:{},audit:[],assetTeam:'technology-team',operatorMetrics:{}};
const q=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),fmt=v=>v?new Date(v).toLocaleString():'—';
let controlPlaneKey=localStorage.getItem('integration-fabric-control-plane-key')||'';
async function api(url,options={},retry=true){const headers={...(options.headers||{})};if(controlPlaneKey)headers['X-Admin-Key']=controlPlaneKey;const response=await fetch(url,{...options,headers});if(response.status===401&&retry){const entered=window.prompt('Enter the Control Plane credential');if(entered){controlPlaneKey=entered.trim();localStorage.setItem('integration-fabric-control-plane-key',controlPlaneKey);return api(url,options,false)}localStorage.removeItem('integration-fabric-control-plane-key');controlPlaneKey=''}if(!response.ok){let message=response.statusText;try{message=(await response.json()).detail||message}catch{}throw Error(message)}return response.status===204?null:response.json()}
function toast(message,error=false){const el=q('#toast');el.textContent=message;el.className=error?'error':'';el.style.display='block';clearTimeout(el.timer);el.timer=setTimeout(()=>el.style.display='none',4200)}
function status(value){const text=String(value||'UNKNOWN');return `<span class="state ${text.toLowerCase()}">${esc(text)}</span>`}
function panel(title,subtitle,body,action=''){return `<section class="panel"><div class="panel-title"><div><h2>${esc(title)}</h2><small>${esc(subtitle)}</small></div>${action}</div>${body}</section>`}
function metric(value,label,detail=''){return `<article><b>${esc(value)}</b><small>${esc(label)}</small>${detail?`<em>${esc(detail)}</em>`:''}</article>`}
function setStats(values){q('#stats').innerHTML=values.join('')}
function action(label,handler){q('#pageActions').innerHTML=`<button class="primary" id="pageAction">${esc(label)}</button>`;q('#pageAction').onclick=handler}
function noAction(){q('#pageActions').innerHTML=''}
function tags(values=[]){return `<div class="tags">${values.map(value=>`<em>${esc(value)}</em>`).join('')}</div>`}
function planeName(id){return state.dataPlanes.find(x=>x.id===id)?.name||id||'—'}
function teamName(id){return state.teams.find(x=>x.id===id)?.name||id||'—'}

function renderHome(){const o=state.overview,dp=o.dataPlanes||{},cap=o.capabilities||{},apps=o.applications||{};setStats([metric(`${dp.running||0}/${dp.total||0}`,'DATA PLANES RUNNING',`${dp.warning||0} warning · ${dp.critical||0} critical`),metric(`${cap.running||0}/${cap.total||0}`,'CAPABILITIES HEALTHY'),metric(apps.deployments||0,'APPLICATION DEPLOYMENTS',`${apps.runningInstances||0} running instances`),metric(state.observability.summary?.requestCount||0,'CONTROL PLANE REQUESTS',`${state.observability.summary?.errorRate||0}% error rate`)]);noAction();const planeRows=state.dataPlanes.map(x=>`<div class="asset-row"><div><b>${esc(x.name)}</b><small>${esc(x.type)} · ${esc(x.region)}</small></div>${status(x.status)}<span>${x.capabilityCount||0} capabilities</span><span>${x.applicationCount||0} applications</span><time>${fmt(x.lastHeartbeat)}</time></div>`).join('')||'<div class="empty">No data planes registered.</div>';const activity=(o.recentActivity||[]).map(x=>`<div class="timeline"><i></i><div><b>${esc(x.action)}</b><span>${esc(x.target)}</span><small>${esc(x.detail)}</small></div><time>${fmt(x.time)}</time></div>`).join('')||'<div class="empty">No recent activity.</div>';q('#content').innerHTML=panel('Data-plane status','Health reported through registered management tunnels',`<div class="asset-list">${planeRows}</div>`)+panel('Recent control-plane activity','Latest provisioning, deployment, and governance operations',`<div class="timeline-list">${activity}</div>`)}
function renderDataPlanes(){const running=state.dataPlanes.filter(x=>x.status==='ONLINE').length;setStats([metric(state.dataPlanes.length,'REGISTERED'),metric(running,'RUNNING'),metric(state.dataPlanes.filter(x=>x.type==='kubernetes').length,'KUBERNETES'),metric(state.dataPlanes.reduce((n,x)=>n+(x.applicationCount||0),0),'APPLICATIONS')]);action('Register data plane',()=>q('#dataPlaneDialog').showModal());q('#content').innerHTML=panel('Data planes','Logical runtime boundaries across Kubernetes and on-premises infrastructure',`<div class="cards">${state.dataPlanes.map(x=>`<article class="card plane-card"><div class="card-head"><div><small>${esc(x.type).toUpperCase()}</small><b>${esc(x.name)}</b></div>${status(x.status)}</div><dl><dt>Region</dt><dd>${esc(x.region)}</dd><dt>Management tunnel</dt><dd>${esc(x.tunnelStatus)}</dd><dt>Capabilities</dt><dd>${x.capabilityCount||0}</dd><dt>Applications</dt><dd>${x.applicationCount||0}</dd><dt>Capacity</dt><dd>${x.capacity||0}</dd><dt>Last heartbeat</dt><dd>${fmt(x.lastHeartbeat)}</dd></dl>${tags(x.tags)}<div class="actions"><button onclick="dataPlaneDetails('${esc(x.id)}')">View configuration</button><button onclick="editDataPlane('${esc(x.id)}')">Edit</button></div></article>`).join('')}</div>`)}
function renderCapabilities(){setStats([metric(state.capabilities.length,'PROVISIONED'),metric(state.capabilities.filter(x=>x.health==='RUNNING').length,'RUNNING'),metric(new Set(state.capabilities.map(x=>x.dataPlaneId)).size,'DATA PLANES'),metric(new Set(state.capabilities.map(x=>x.type)).size,'CAPABILITY TYPES')]);action('Provision capability',openCapability);q('#content').innerHTML=panel('Capabilities','Product runtimes provisioned into data-plane namespaces',`<div class="cards">${state.capabilities.map(x=>`<article class="card"><div class="card-head"><div><small>${esc(x.type).toUpperCase()}</small><b>${esc(x.name)}</b></div>${status(x.health)}</div><dl><dt>Version</dt><dd>${esc(x.version)}</dd><dt>Data plane</dt><dd>${esc(planeName(x.dataPlaneId))}</dd><dt>Namespace</dt><dd>${esc(x.namespace)}</dd><dt>State</dt><dd>${esc(x.state)}</dd></dl>${tags(x.tags)}<button onclick="editCapability('${esc(x.id)}')">Edit configuration</button></article>`).join('')||'<div class="empty">No capabilities provisioned.</div>'}</div>`)}
function renderApplications(){const packages=state.applications.length,running=state.deployments.filter(x=>x.state==='RUNNING').length,failed=state.deployments.filter(x=>x.state==='FAILED').length;setStats([metric(packages,'PACKAGES'),metric(state.deployments.filter(x=>x.state!=='UNDEPLOYED').length,'DEPLOYMENTS'),metric(running,'RUNNING'),metric(failed,'FAILED')]);q('#pageActions').innerHTML=`<input id="applicationSearch" type="search" placeholder="Search applications, packages, environments…"><select id="assetTeamPicker" title="Team ownership">${state.teams.filter(x=>x.status==='ACTIVE').map(x=>`<option value="${esc(x.id)}" ${x.id===state.assetTeam?'selected':''}>${esc(x.name)}</option>`).join('')}</select><button class="primary" id="pageAction">Upload package</button>`;q('#assetTeamPicker').onchange=e=>state.assetTeam=e.target.value;q('#pageAction').onclick=()=>q('#packageFile').click();const deployments=state.deployments.filter(x=>x.state!=='UNDEPLOYED').map(x=>`<div class="app-row searchable" data-search="${esc(`${x.application} ${x.packageId} ${x.environment} ${x.state} ${planeName(x.dataPlaneId||x.machine)}`.toLowerCase())}"><div><b>${esc(x.application)}</b><small>${esc(x.packageId)} · ${esc(x.environment)} · ${esc(teamName(x.teamId))}</small></div><span>${esc(planeName(x.dataPlaneId||x.machine))}<small>${esc(x.namespace||'default')}</small></span><span>${status(x.state)} ${status(x.health?.status||'PENDING')}</span><b>${(x.instances||[]).length}/${x.desiredInstances}</b><div class="actions"><button onclick="details('${esc(x.id)}')">Manage</button>${x.state==='RUNNING'?`<button onclick="lifecycle('${x.id}','stop')">Stop</button>`:`<button onclick="lifecycle('${x.id}','start')">Start</button>`}<button class="danger" onclick="lifecycle('${x.id}','undeploy')">Undeploy</button></div></div>`).join('')||'<div class="empty">No application deployments.</div>';const packagesHtml=state.applications.map(x=>`<div class="package searchable" data-search="${esc(`${x.applicationName} ${x.packageId} ${x.target} ${(x.environments||[]).join(' ')}`.toLowerCase())}"><div><b>${esc(x.applicationName)}</b><small>${esc(x.packageId)} · ${esc(x.target)} · ${x.fileCount||0} files · ${esc(teamName(x.teamId))}</small></div>${status(x.status)}<span>${(x.environments||[]).map(e=>`<em>${esc(e)}</em>`).join('')}</span><div class="actions"><button onclick="packageDetails('${esc(x.packageId)}','${esc(x.teamId)}')">Archive</button><button onclick="openDeploy('${esc(x.packageId)}','${esc(x.teamId)}')">Deploy</button><button class="danger" onclick="deletePackage('${esc(x.packageId)}','${esc(x.teamId)}')">Delete</button></div></div>`).join('')||'<div class="empty">Upload an MINA deployment package.</div>';q('#content').innerHTML=panel('Application deployments','Search, health, lifecycle, configuration, Starter Tasks, and revision history',`<div class="app-list">${deployments}</div>`)+panel('Team-isolated application package repository','Inspect archive tasks, deploy, review profiles, revisions, or delete unused packages',`<div class="package-list">${packagesHtml}</div>`);q('#applicationSearch').oninput=e=>document.querySelectorAll('#content .searchable').forEach(row=>row.hidden=!row.dataset.search.includes(e.target.value.trim().toLowerCase()))}
function renderEnvironments(){setStats([metric(state.applications.reduce((n,x)=>n+(x.environments||[]).length,0),'PROFILES'),metric(state.applications.reduce((n,x)=>n+Object.values(x.secretKeysByEnvironment||{}).flat().length,0),'SECRET REQUIREMENTS'),metric(state.deployments.length,'DEPLOYMENT SCOPES'),metric('ENCRYPTED','SECRET STORAGE')]);noAction();q('#content').innerHTML=panel('Environment profiles and secret requirements','Export for review, edit or upload a non-secret profile, and optionally redeploy running applications',`<div class="cards">${state.applications.map(pkg=>`<article class="card"><div class="card-head"><div><b>${esc(pkg.applicationName)}</b><small>${esc(pkg.packageId)}</small></div></div>${(pkg.environments||[]).map(env=>`<div class="environment profile-row"><b>${esc(env)}</b><span>${((pkg.secretKeysByEnvironment||{})[env]||[]).length} required secrets</span>${tags((pkg.secretKeysByEnvironment||{})[env]||[])}<div class="actions"><button onclick="exportProfile('${esc(pkg.packageId)}','${esc(pkg.teamId)}','${esc(env)}')">Export</button><button onclick="editProfile('${esc(pkg.packageId)}','${esc(pkg.teamId)}','${esc(env)}')">Edit / upload</button></div></div>`).join('')}</article>`).join('')||'<div class="empty">Environment profiles appear after package upload.</div>'}</div>`)}
function renderObservability(){const o=state.observability,s=o.summary||{};setStats([metric(s.requestCount||0,'REQUEST COUNT'),metric(`${s.errorRate||0}%`,'ERROR RATE'),metric(s.runningInstances||0,'RUNNING INSTANCES'),metric(s.applications||0,'APPLICATIONS')]);noAction();const planes=(o.dataPlanes||[]).map(x=>`<div class="telemetry-row"><div><b>${esc(x.name)}</b><small>${esc(x.id)}</small></div>${status(x.status)}<span>CPU ${x.cpuPercent??'—'}%</span><span>MEM ${x.memoryPercent??'—'}%</span><time>${fmt(x.lastHeartbeat)}</time></div>`).join('');const routes=Object.entries(o.requests?.routes||{}).sort((a,b)=>b[1]-a[1]).slice(0,12).map(([name,count])=>`<div class="bar"><span>${esc(name)}</span><i style="--value:${Math.min(100,Number(count))}%"></i><b>${count}</b></div>`).join('');q('#content').innerHTML=panel('Data-plane observability','Health, tunnel connectivity, CPU, and memory reported by runtime agents',`<div class="telemetry">${planes||'<div class="empty">No data-plane telemetry.</div>'}</div>`)+panel('Control-plane request activity','Top API routes since process startup',`<div class="bars">${routes||'<div class="empty">No request telemetry.</div>'}</div>`)}
function renderResources(){setStats([metric(state.resources.length,'CONFIGURED'),metric(state.resources.filter(x=>x.scope==='global').length,'GLOBAL'),metric(state.resources.filter(x=>x.type==='observability').length,'OBSERVABILITY'),metric(state.resources.filter(x=>x.type==='ingress').length,'INGRESS')]);action('Configure resource',openResource);q('#content').innerHTML=panel('Platform resources','Global and data-plane scoped observability, ingress, storage, identity, and secret providers',`<div class="cards">${state.resources.map(x=>`<article class="card"><div class="card-head"><div><small>${esc(x.type).toUpperCase()}</small><b>${esc(x.name)}</b></div>${status(x.state)}</div><dl><dt>Scope</dt><dd>${esc(x.scope)}</dd><dt>Data plane</dt><dd>${esc(x.dataPlaneId==='*'?'All data planes':planeName(x.dataPlaneId))}</dd><dt>Updated</dt><dd>${fmt(x.updatedAt)}</dd></dl>${tags(x.tags)}</article>`).join('')||'<div class="empty">No resources configured.</div>'}</div>`)}
function renderTeams(){const delivery=state.teams.filter(x=>x.kind==='delivery'&&x.status==='ACTIVE');setStats([metric(state.teams.filter(x=>x.status==='ACTIVE').length,'ACTIVE TEAMS'),metric(delivery.length,'DELIVERY TEAMS'),metric(delivery.reduce((n,x)=>n+(x.namespaceScopes||[]).length,0),'ISOLATED NAMESPACES'),metric('TECHNOLOGY','CONTROL PLANE OWNER')]);action('Provision delivery team',openTeam);q('#content').innerHTML=panel('Technology Team','Exclusive Control Plane ownership and enterprise governance',`<div class="notice"><b>Technology Team manages the Control Plane.</b><br>Delivery teams receive application APIs and isolated namespaces only; they cannot open governance, data-plane, capability, resource, access, monitoring, or audit APIs.</div>`)+panel('Delivery teams','Assets, packages, deployments, secrets, logs, and telemetry are isolated by owning team',`<div class="cards">${delivery.map(x=>`<article class="card"><div class="card-head"><div><small>DELIVERY TEAM</small><b>${esc(x.name)}</b></div>${status(x.status)}</div><p>${esc(x.description||'Data delivery team')}</p><h3>Namespace assignments</h3>${tags((x.namespaceScopes||[]).map(s=>`${planeName(s.dataPlaneId)} / ${s.namespace}`))}<dl><dt>Packages</dt><dd>${x.packageCount||0}</dd><dt>Deployments</dt><dd>${x.deploymentCount||0}</dd><dt>Control Plane access</dt><dd>Denied</dd></dl><button onclick="issueTeamToken('${esc(x.id)}')">Issue automation credential</button></article>`).join('')||'<div class="empty">Provision a delivery team and assign its exclusive namespaces.</div>'}</div>`)}
function renderAccess(){setStats([metric(state.principals.length,'PRINCIPALS'),metric(state.principals.filter(x=>x.type==='user').length,'USERS'),metric(state.teams.filter(x=>x.kind==='delivery'&&x.status==='ACTIVE').length,'DELIVERY TEAMS'),metric(state.principals.filter(x=>x.type==='idp-group').length,'IDP GROUPS')]);action('Add principal',openPrincipal);q('#content').innerHTML=panel('Access control','Technology-owned RBAC with principals bound to exactly one team',`<div class="access-list">${state.principals.map(x=>`<div class="principal"><div class="avatar">${esc(x.name.slice(0,2).toUpperCase())}</div><div><b>${esc(x.name)}</b><small>${esc(x.type)} · ${esc(x.status)} · ${esc(teamName(x.teamId))}</small></div><div>${(x.permissions||[]).map(p=>`<span class="permission"><b>${esc(p.role)}</b><small>${esc(p.scope)} · ${esc(p.resourceId)}</small></span>`).join('')}</div></div>`).join('')}</div>`)}
function renderAudit(){setStats([metric(state.audit.length,'RECENT EVENTS'),metric(state.audit.filter(x=>x.outcome==='success').length,'SUCCESS'),metric(state.audit.filter(x=>x.outcome==='failure').length,'FAILURE'),metric(new Set(state.audit.map(x=>x.action)).size,'ACTION TYPES')]);noAction();q('#content').innerHTML=panel('Audit trail','Operational record for package, data-plane, capability, application, resource, secret, and access changes',`<div class="audit">${state.audit.map(x=>`<div><time>${fmt(x.time)}</time>${status(x.outcome.toUpperCase())}<b>${esc(x.action)}</b><span>${esc(x.target)}</span><small>${esc(x.detail)}</small></div>`).join('')||'<div class="empty">No audit activity.</div>'}</div>`)}
function render(){({home:renderHome,dataPlanes:renderDataPlanes,capabilities:renderCapabilities,applications:renderApplications,environments:renderEnvironments,observability:renderObservability,resources:renderResources,teams:renderTeams,access:renderAccess,audit:renderAudit}[state.view])()}
const pageMeta={home:['CONTROL PLANE','Platform overview','Manage every MINA data plane, capability, team, and application.'],dataPlanes:['INFRASTRUCTURE','Machines & data planes','Register, inspect, and operate remote runtime machines and their namespaces.'],capabilities:['PLATFORM SERVICES','Capabilities','Provision Integration Runtime capabilities into data-plane namespaces.'],applications:['APPLICATIONS','Application lifecycle','Deploy, scale, stop, restart, and inspect team-owned applications.'],environments:['CONFIGURATION','Environments & secrets','Review team-isolated profile configuration and encrypted secret requirements.'],observability:['OBSERVE','Runtime telemetry','Monitor live CPU, RAM, disk, execution outcomes, and Control Plane requests.'],resources:['INFRASTRUCTURE','Platform resources','Configure global or data-plane observability, ingress, storage, and identity resources.'],teams:['GOVERN','Delivery teams','Provision exclusive namespaces and team-scoped application credentials.'],access:['GOVERN','Access control','Bind users and identity-provider groups to Technology or delivery teams.'],audit:['GOVERN','Audit trail','Trace every control-plane change and lifecycle operation.']};
q('#nav').onclick=e=>{const button=e.target.closest('[data-view]');if(!button)return;state.view=button.dataset.view;q('#nav .active')?.classList.remove('active');button.classList.add('active');const meta=pageMeta[state.view];q('#eyebrow').textContent=meta[0];q('#pageTitle').textContent=meta[1];q('#pageDescription').textContent=meta[2];render()};
function populatePlaneSelect(select,includeGlobal=false){select.innerHTML=(includeGlobal?'<option value="*">All data planes</option>':'')+state.dataPlanes.map(x=>`<option value="${esc(x.id)}">${esc(x.name)} · ${esc(x.status)}</option>`).join('')}
function namespaces(planeId){return state.dataPlanes.find(x=>x.id===planeId)?.namespaces||['default']}
function openCapability(){populatePlaneSelect(q('#capabilityPlane'));const refresh=()=>q('#capabilityNamespace').innerHTML=namespaces(q('#capabilityPlane').value).map(x=>`<option>${esc(x)}</option>`).join('');q('#capabilityPlane').onchange=refresh;refresh();q('#capabilityDialog').showModal()}
function openResource(){populatePlaneSelect(q('#resourcePlane'),true);q('#resourceScope').onchange=()=>{q('#resourcePlane').value=q('#resourceScope').value==='global'?'*':state.dataPlanes[0]?.id||'*'};q('#resourceDialog').showModal()}
function openTeam(){q('#teamScopes').innerHTML=state.dataPlanes.flatMap(plane=>(plane.namespaces||[]).map(namespace=>`<label><input type="checkbox" data-plane="${esc(plane.id)}" data-namespace="${esc(namespace)}"><span><b>${esc(namespace)}</b><small>${esc(plane.name)}</small></span></label>`)).join('');q('#teamDialog').showModal()}
function openPrincipal(){populatePlaneSelect(q('#principalResource'),true);q('#principalTeam').innerHTML=state.teams.filter(x=>x.status==='ACTIVE').map(x=>`<option value="${esc(x.id)}">${esc(x.name)}</option>`).join('');q('#principalDialog').showModal()}
function openDeploy(packageId,teamId){const pkg=state.applications.find(x=>x.packageId===packageId&&x.teamId===teamId);if(!pkg)return;q('#deployPackageId').value=packageId;q('#deployTeamId').value=teamId;q('#deployPackage').textContent=`${pkg.applicationName} · ${packageId} · ${teamName(teamId)}`;q('#deployEnvironment').innerHTML=(pkg.environments||[]).map(x=>`<option>${esc(x)}</option>`).join('');const owner=state.teams.find(x=>x.id===teamId),scopes=teamId==='technology-team'?null:(owner?.namespaceScopes||[]);const allowedPlanes=state.dataPlanes.filter(x=>!scopes||scopes.some(s=>s.dataPlaneId===x.id));q('#deployDataPlane').innerHTML=allowedPlanes.map(x=>`<option value="${esc(x.id)}">${esc(x.name)} · ${esc(x.status)}</option>`).join('');const refresh=()=>{const plane=q('#deployDataPlane').value,allowedNamespaces=scopes?scopes.filter(s=>s.dataPlaneId===plane).map(s=>s.namespace):namespaces(plane);q('#deployNamespace').innerHTML=allowedNamespaces.map(x=>`<option>${esc(x)}</option>`).join('');const updateCaps=()=>{const ns=q('#deployNamespace').value;q('#deployCapability').innerHTML=state.capabilities.filter(x=>x.dataPlaneId===plane&&x.namespace===ns&&x.type==='integration-runtime').map(x=>`<option value="${esc(x.id)}">${esc(x.name)} · ${esc(x.version)}</option>`).join('')};q('#deployNamespace').onchange=updateCaps;updateCaps()};q('#deployDataPlane').onchange=refresh;refresh();const secretRefresh=()=>{const keys=(pkg.secretKeysByEnvironment||{})[q('#deployEnvironment').value]||[];q('#secretFields').innerHTML=keys.length?`<h3>Required secrets</h3><p class="notice">Encrypted at rest and isolated to ${esc(teamName(teamId))}.</p><div class="form-grid">${keys.map(k=>`<label>${esc(k)}<input class="secret" data-key="${esc(k)}" type="password" required></label>`).join('')}</div>`:'<p class="notice success">No secrets required for this profile.</p>'};q('#deployEnvironment').onchange=secretRefresh;secretRefresh();q('#deploymentDialog').showModal()}
async function issueTeamToken(teamId){try{const output=await api(`/api/teams/${encodeURIComponent(teamId)}/tokens`,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({name:`${teamName(teamId)} automation`,roles:['Application Manager']})});q('#detailsTitle').textContent='Automation credential created';q('#detailsSubtitle').textContent=`${teamName(teamId)} · shown once`;q('#detailsContent').innerHTML=`<p class="notice success">Copy this credential now. Only its SHA-256 hash is stored by the Control Plane.</p><pre>${esc(output.token)}</pre><p>Send it as <code>X-Control-Plane-Key</code>. It can access only ${esc(teamName(teamId))} packages, deployments, logs, secrets, and observability.</p>`;q('#detailsDialog').showModal()}catch(error){toast(error.message,true)}}
async function lifecycle(id,name){if((name==='kill'||name==='undeploy')&&!confirm(`${name} this application deployment?`))return;try{await api(`/api/deployments/${id}/${name}`,{method:'POST'});toast(`${name} completed`);await load()}catch(error){toast(error.message,true);await load()}}
async function packageDetails(packageId,teamId){try{const [artifact,version]=packageId.split(':'),item=await api(`/api/packages/${encodeURIComponent(artifact)}/${encodeURIComponent(version)}?teamId=${encodeURIComponent(teamId)}`),revisions=await api(`/api/revisions/package/${encodeURIComponent(packageId)}`);q('#detailsTitle').textContent=item.applicationName;q('#detailsSubtitle').textContent=`${packageId} · archive contents`;q('#detailsContent').innerHTML=`<div class="detail-grid"><div><small>TARGET</small><b>${esc(item.target)}</b></div><div><small>FILES</small><b>${item.fileCount||0}</b></div><div><small>STARTERS</small><b>${(item.tasks||[]).filter(x=>x.starter).length}</b></div><div><small>CHECKSUM</small><b title="${esc(item.sha256)}">${esc((item.sha256||'—').slice(0,12))}</b></div></div><h3>Packaged tasks</h3><div class="task-inventory">${(item.tasks||[]).map(task=>`<article><div><b>${esc(task.name)}</b><small>${esc(task.id)} · ${task.activityCount} activities</small></div>${status(task.starter?'STARTER':'SUB TASK')}</article>`).join('')||'<div class="empty">No task descriptors found.</div>'}</div><h3>Environment profiles</h3>${tags(item.environments||[])}<h3>Revision history</h3>${revisionHtml(revisions)}`;q('#detailsDialog').showModal()}catch(error){toast(error.message,true)}}
async function deletePackage(packageId,teamId){if(!confirm(`Delete package ${packageId}? Active deployments must be undeployed first.`))return;try{const [artifact,version]=packageId.split(':');await api(`/api/packages/${encodeURIComponent(artifact)}/${encodeURIComponent(version)}?teamId=${encodeURIComponent(teamId)}`,{method:'DELETE'});toast('Package deleted');await load()}catch(error){toast(error.message,true)}}
function revisionHtml(values){return `<div class="revision-list">${(values||[]).map(value=>`<article><b>Revision ${value.revision} · ${esc(value.action)}</b><small>${fmt(value.time)} · ${esc(value.actor)}</small><p>${esc(value.detail||'')}</p></article>`).join('')||'<div class="empty">No revisions recorded yet.</div>'}</div>`}
async function details(id){try{const item=await api(`/api/deployments/${id}`),logs=await api(`/api/deployments/${id}/logs`),revisions=await api(`/api/revisions/deployment/${encodeURIComponent(id)}`),pkg=state.applications.find(x=>x.packageId===item.packageId&&x.teamId===item.teamId);q('#detailsTitle').textContent=item.application;q('#detailsSubtitle').textContent=`${item.packageId} · ${planeName(item.dataPlaneId||item.machine)} · ${item.namespace||'default'}`;const starters=(pkg?.starterTaskIds||Object.keys(item.starterStates||{}));q('#detailsContent').innerHTML=`<div class="detail-grid"><div><small>STATE</small>${status(item.state)}</div><div><small>HEALTH</small>${status(item.health?.status)}</div><div><small>ENVIRONMENT</small><b>${esc(item.environment)}</b></div><div><small>INSTANCES</small><b>${(item.instances||[]).length}/${item.desiredInstances}</b></div></div>${item.lastError?`<p class="notice failure">${esc(item.lastError)}</p>`:''}<h3>Deployment configuration</h3><div class="form-grid manage-config"><label>Environment<select id="manageEnvironment">${(pkg?.environments||[item.environment]).map(x=>`<option ${x===item.environment?'selected':''}>${esc(x)}</option>`).join('')}</select></label><label>Desired instances<input id="manageInstances" type="number" min="1" max="100" value="${item.desiredInstances}"></label><label>Health checks<select id="manageHealth"><option value="true" ${item.healthCheckEnabled!==false?'selected':''}>Enabled</option><option value="false" ${item.healthCheckEnabled===false?'selected':''}>Disabled</option></select></label><label>Updated secrets (JSON, optional)<textarea id="manageSecrets" rows="3">{}</textarea></label></div><div class="actions manage-actions"><button onclick="saveDeploymentConfig('${esc(id)}',false)">Save</button><button class="primary" onclick="saveDeploymentConfig('${esc(id)}',true)">Save & redeploy</button></div><h3>Starter Tasks</h3><div class="starter-list">${starters.map(taskId=>{const task=(pkg?.tasks||[]).find(x=>x.id===taskId),started=(item.starterStates||{})[taskId]!=='STOPPED';return `<article><div><b>${esc(task?.name||taskId)}</b><small>${esc(taskId)}</small></div>${status(started?'STARTED':'STOPPED')}<button onclick="starterLifecycle('${esc(id)}','${esc(taskId)}','${started?'stop':'start'}')">${started?'Stop':'Start'}</button></article>`}).join('')||'<div class="empty">No Starter Task metadata available.</div>'}</div><h3>Revision history</h3>${revisionHtml(revisions)}<h3>Runtime logs</h3>${logs.map(x=>`<small>${esc(x.instanceId)}</small><pre>${esc(x.lines.join('\n'))}</pre>`).join('')||'<div class="empty">No runtime logs.</div>'}`;q('#detailsDialog').showModal()}catch(error){toast(error.message,true)}}
async function saveDeploymentConfig(id,redeploy){try{const secrets=JSON.parse(q('#manageSecrets').value||'{}');await api(`/api/deployments/${id}/configuration`,{method:'PUT',headers:{'content-type':'application/json'},body:JSON.stringify({environment:q('#manageEnvironment').value,instances:Number(q('#manageInstances').value),healthCheckEnabled:q('#manageHealth').value==='true',secrets,redeploy})});toast(redeploy?'Configuration redeployed':'Configuration saved');await load();await details(id)}catch(error){toast(error.message,true)}}
async function starterLifecycle(deploymentId,taskId,action){try{await api(`/api/deployments/${deploymentId}/starters/${encodeURIComponent(taskId)}/${action}`,{method:'POST'});toast(`Starter ${action} completed`);await load();await details(deploymentId)}catch(error){toast(error.message,true)}}
async function exportProfile(packageId,teamId,environment){try{const [artifact,version]=packageId.split(':'),response=await fetch(`/api/packages/${encodeURIComponent(artifact)}/${encodeURIComponent(version)}/environments/${encodeURIComponent(environment)}?teamId=${encodeURIComponent(teamId)}`);if(!response.ok)throw Error((await response.json()).detail||'Export failed');const blob=await response.blob(),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`${artifact}-${environment}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}catch(error){toast(error.message,true)}}
async function editProfile(packageId,teamId,environment){try{const [artifact,version]=packageId.split(':'),values=await api(`/api/packages/${encodeURIComponent(artifact)}/${encodeURIComponent(version)}/environments/${encodeURIComponent(environment)}?teamId=${encodeURIComponent(teamId)}`);q('#detailsTitle').textContent=`${environment} environment profile`;q('#detailsSubtitle').textContent=`${packageId} · password values must remain blank`;q('#detailsContent').innerHTML=`<p class="notice">Edit the profile JSON or choose a previously exported profile. Secret values remain deployment-scoped.</p><input id="profileUpload" type="file" accept=".json,application/json"><textarea id="profileEditor" class="profile-editor" rows="20">${esc(JSON.stringify(values,null,2))}</textarea><label class="profile-redeploy"><input id="profileRedeploy" type="checkbox" checked> Redeploy running applications using this profile</label><div class="actions manage-actions"><button class="primary" onclick="saveProfile('${esc(packageId)}','${esc(teamId)}','${esc(environment)}')">Save profile</button></div>`;q('#profileUpload').onchange=async e=>{if(e.target.files[0])q('#profileEditor').value=await e.target.files[0].text()};q('#detailsDialog').showModal()}catch(error){toast(error.message,true)}}
async function saveProfile(packageId,teamId,environment){try{const [artifact,version]=packageId.split(':'),parsed=JSON.parse(q('#profileEditor').value),values=Array.isArray(parsed)?parsed:parsed.values;if(!Array.isArray(values))throw Error('Profile must be an array or an object containing values');const result=await api(`/api/packages/${encodeURIComponent(artifact)}/${encodeURIComponent(version)}/environments/${encodeURIComponent(environment)}?teamId=${encodeURIComponent(teamId)}`,{method:'PUT',headers:{'content-type':'application/json'},body:JSON.stringify({values,redeploy:q('#profileRedeploy').checked})});toast(`Profile revision ${result.revision} saved`);q('#detailsDialog').close();await load()}catch(error){toast(error.message,true)}}
async function dataPlaneDetails(id){try{const x=await api(`/api/data-planes/${id}`);q('#detailsTitle').textContent=x.name;q('#detailsSubtitle').textContent=`${x.type} · ${x.region} · ${x.id}`;q('#detailsContent').innerHTML=`<div class="detail-grid"><div><small>STATUS</small>${status(x.status)}</div><div><small>TUNNEL</small><b>${esc(x.tunnelStatus)}</b></div><div><small>CAPABILITIES</small><b>${x.capabilityCount}</b></div><div><small>APPLICATIONS</small><b>${x.applicationCount}</b></div></div><h3>Namespaces</h3>${tags(x.namespaces)}<h3>Registration</h3><p class="notice">Agent heartbeat endpoint: <code>/api/data-planes/${esc(x.id)}/heartbeat</code></p>`;q('#detailsDialog').showModal()}catch(error){toast(error.message,true)}}
document.querySelectorAll('[data-close]').forEach(x=>x.onclick=()=>x.closest('dialog').close());
q('#packageFile').onchange=async e=>{if(!e.target.files[0])return;const data=new FormData();data.append('file',e.target.files[0]);try{await api(`/api/packages?teamId=${encodeURIComponent(state.assetTeam)}`,{method:'POST',body:data});toast(`Package validated for ${teamName(state.assetTeam)}`);await load()}catch(error){toast(error.message,true)}e.target.value=''};
q('#deploymentForm').onsubmit=async e=>{e.preventDefault();const secrets={};document.querySelectorAll('#secretFields .secret').forEach(x=>secrets[x.dataset.key]=x.value);try{await api('/api/deployments',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({packageId:q('#deployPackageId').value,teamId:q('#deployTeamId').value,environment:q('#deployEnvironment').value,dataPlaneId:q('#deployDataPlane').value,namespace:q('#deployNamespace').value,capabilityId:q('#deployCapability').value,instances:Number(q('#deployInstances').value),secrets})});q('#deploymentDialog').close();toast('Team-isolated application deployment created');await load()}catch(error){toast(error.message,true)}};
q('#dataPlaneForm').onsubmit=async e=>{e.preventDefault();try{await api('/api/data-planes',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({name:q('#planeName').value,type:q('#planeType').value,host:q('#planeHost').value,region:q('#planeRegion').value,namespaces:q('#planeNamespaces').value.split(',').map(x=>x.trim()).filter(Boolean),tags:q('#planeTags').value.split(',').map(x=>x.trim()).filter(Boolean),capacity:Number(q('#planeCapacity').value)})});q('#dataPlaneDialog').close();e.target.reset();toast('Data plane registered');await load()}catch(error){toast(error.message,true)}};
q('#capabilityForm').onsubmit=async e=>{e.preventDefault();try{await api('/api/capabilities',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({name:q('#capabilityName').value,type:q('#capabilityType').value,version:q('#capabilityVersion').value,dataPlaneId:q('#capabilityPlane').value,namespace:q('#capabilityNamespace').value})});q('#capabilityDialog').close();toast('Capability provisioned');await load()}catch(error){toast(error.message,true)}};
q('#resourceForm').onsubmit=async e=>{e.preventDefault();try{const global=q('#resourceScope').value==='global';await api('/api/resources',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({name:q('#resourceName').value,type:q('#resourceType').value,scope:q('#resourceScope').value,dataPlaneId:global?'*':q('#resourcePlane').value,configuration:JSON.parse(q('#resourceConfiguration').value||'{}')})});q('#resourceDialog').close();toast('Resource configured');await load()}catch(error){toast(error.message,true)}};
q('#teamForm').onsubmit=async e=>{e.preventDefault();const namespaceScopes=[...document.querySelectorAll('#teamScopes input:checked')].map(x=>({dataPlaneId:x.dataset.plane,namespace:x.dataset.namespace}));try{await api('/api/teams',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({id:q('#teamId').value,name:q('#teamName').value,description:q('#teamDescription').value,kind:'delivery',namespaceScopes})});q('#teamDialog').close();e.target.reset();toast('Delivery team provisioned with isolated namespaces');await load()}catch(error){toast(error.message,true)}};
q('#principalForm').onsubmit=async e=>{e.preventDefault();try{await api('/api/access/principals',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({name:q('#principalName').value,type:q('#principalType').value,teamId:q('#principalTeam').value,permissions:[{role:q('#principalRole').value,scope:q('#principalScope').value,resourceId:q('#principalResource').value}]})});q('#principalDialog').close();toast('Access principal created');await load()}catch(error){toast(error.message,true)}};
async function load(){try{const [health,session,teams]=await Promise.all(['/api/health','/api/session','/api/teams'].map(url=>api(url)));const [overview,dataPlanes,capabilities,applications,deployments,resources,principals,observability,audit]=await Promise.all(['/api/control-plane/overview','/api/data-planes','/api/capabilities','/api/applications','/api/deployments','/api/resources','/api/access/principals','/api/observability','/api/audit?limit=250'].map(url=>api(url)));Object.assign(state,{health,session,teams,overview,dataPlanes,capabilities,applications,deployments,resources,principals,observability,audit});if(!state.teams.some(x=>x.id===state.assetTeam))state.assetTeam='technology-team';q('#health').textContent=`ONLINE · v${health.version}`;q('#health').classList.remove('offline');q('#version').textContent=health.version;render()}catch(error){q('#health').textContent='CONTROL PLANE OFFLINE';q('#health').classList.add('offline');toast(error.message,true)}}
async function editDataPlane(id){const x=state.dataPlanes.find(v=>v.id===id);if(!x)return;const name=prompt('Data plane name',x.name);if(!name||name===x.name)return;try{await api(`/api/data-planes/${id}`,{method:'PUT',headers:{'content-type':'application/json'},body:JSON.stringify({...x,id,name})});toast('Data plane updated');await load()}catch(e){toast(e.message,true)}}
async function editCapability(id){const x=state.capabilities.find(v=>v.id===id);if(!x)return;const name=prompt('Capability name',x.name);if(!name||name===x.name)return;try{await api(`/api/capabilities/${id}`,{method:'PUT',headers:{'content-type':'application/json'},body:JSON.stringify(x={...x,name})});toast('Capability updated');await load()}catch(e){toast(e.message,true)}}
async function editTeam(id){const x=state.teams.find(v=>v.id===id);if(!x)return;const name=prompt('Delivery team name',x.name);if(!name||name===x.name)return;try{await api(`/api/teams/${id}`,{method:'PUT',headers:{'content-type':'application/json'},body:JSON.stringify({...x,id})});toast('Delivery team updated');await load()}catch(e){toast(e.message,true)}}
async function editPrincipal(id){const x=state.principals.find(v=>v.id===id);if(!x)return;const name=prompt('User/principal name',x.name);if(!name||name===x.name)return;try{await api(`/api/access/principals/${id}`,{method:'PUT',headers:{'content-type':'application/json'},body:JSON.stringify({...x,name})});toast('User/principal updated');await load()}catch(e){toast(e.message,true)}}
function renderDataPlanes(){setStats([metric(state.dataPlanes.length,'REGISTERED'),metric(state.dataPlanes.filter(x=>x.status==='ONLINE').length,'RUNNING'),metric(state.dataPlanes.filter(x=>x.type==='kubernetes').length,'KUBERNETES'),metric(state.dataPlanes.reduce((n,x)=>n+(x.applicationCount||0),0),'APPLICATIONS')]);action('Register data plane',()=>q('#dataPlaneDialog').showModal());q('#content').innerHTML=panel('Data planes','Logical runtime boundaries across Kubernetes and on-premises infrastructure',`<div class="cards">${state.dataPlanes.map(x=>`<article class="card"><div class="card-head"><div><small>${esc(x.type).toUpperCase()}</small><b>${esc(x.name)}</b></div>${status(x.status)}</div><dl><dt>Region</dt><dd>${esc(x.region)}</dd><dt>Namespaces</dt><dd>${esc((x.namespaces||[]).join(', '))}</dd><dt>Capacity</dt><dd>${x.capacity||0}</dd></dl><div class="actions"><button onclick="dataPlaneDetails('${esc(x.id)}')">View</button><button onclick="editDataPlane('${esc(x.id)}')">Edit</button></div></article>`).join('')}</div>`)}
function renderCapabilities(){setStats([metric(state.capabilities.length,'PROVISIONED'),metric(state.capabilities.filter(x=>x.health==='RUNNING').length,'RUNNING'),metric(new Set(state.capabilities.map(x=>x.dataPlaneId)).size,'DATA PLANES'),metric(new Set(state.capabilities.map(x=>x.type)).size,'CAPABILITY TYPES')]);action('Provision capability',openCapability);q('#content').innerHTML=panel('Capabilities','Product runtimes provisioned into data-plane namespaces',`<div class="cards">${state.capabilities.map(x=>`<article class="card"><div class="card-head"><div><small>${esc(x.type).toUpperCase()}</small><b>${esc(x.name)}</b></div>${status(x.health)}</div><p>${esc(planeName(x.dataPlaneId))} / ${esc(x.namespace)} · ${esc(x.version)}</p><button onclick="editCapability('${esc(x.id)}')">Edit configuration</button></article>`).join('')||'<div class="empty">No capabilities provisioned.</div>'}</div>`)}
function renderTeams(){const delivery=state.teams.filter(x=>x.kind==='delivery'&&x.status==='ACTIVE');setStats([metric(state.teams.filter(x=>x.status==='ACTIVE').length,'ACTIVE TEAMS'),metric(delivery.length,'DELIVERY TEAMS'),metric(delivery.reduce((n,x)=>n+(x.namespaceScopes||[]).length,0),'ISOLATED NAMESPACES'),metric('TECHNOLOGY','CONTROL PLANE OWNER')]);action('Provision delivery team',openTeam);q('#content').innerHTML=panel('Delivery teams','Assets and namespaces isolated by team',`<div class="cards">${delivery.map(x=>`<article class="card"><div class="card-head"><b>${esc(x.name)}</b>${status(x.status)}</div><p>${esc(x.description||'Delivery team')}</p>${tags((x.namespaceScopes||[]).map(s=>`${planeName(s.dataPlaneId)} / ${s.namespace}`))}<div class="actions"><button onclick="editTeam('${esc(x.id)}')">Edit configuration</button><button onclick="issueTeamToken('${esc(x.id)}')">Issue credential</button></div></article>`).join('')||'<div class="empty">No delivery teams.</div>'}</div>`)}
function renderAccess(){setStats([metric(state.principals.length,'PRINCIPALS'),metric(state.principals.filter(x=>x.type==='user').length,'USERS'),metric(state.teams.filter(x=>x.kind==='delivery'&&x.status==='ACTIVE').length,'DELIVERY TEAMS'),metric(state.principals.filter(x=>x.type==='idp-group').length,'IDP GROUPS')]);action('Add principal',openPrincipal);q('#content').innerHTML=panel('Access control','Technology-owned RBAC principals',`<div class="access-list">${state.principals.map(x=>`<div class="principal"><div class="avatar">${esc(x.name.slice(0,2).toUpperCase())}</div><div><b>${esc(x.name)}</b><small>${esc(x.type)} · ${esc(teamName(x.teamId))}</small></div><div class="actions"><button onclick="editPrincipal('${esc(x.id)}')">Edit configuration</button></div></div>`).join('')}</div>`)}
function ensureActionDialog(){let dialog=q('#applicationActionsDialog');if(dialog)return dialog;dialog=document.createElement('dialog');dialog.id='applicationActionsDialog';dialog.innerHTML='<div class="modal-title"><div><h2 id="applicationActionsTitle">Application actions</h2><small id="applicationActionsSubtitle"></small></div><button class="icon" data-close>×</button></div><div id="applicationActionsContent"></div>';document.body.appendChild(dialog);dialog.querySelector('[data-close]').onclick=()=>dialog.close();return dialog}
function ensureLogsDialog(){let dialog=q('#applicationLogsDialog');if(dialog)return dialog;dialog=document.createElement('dialog');dialog.id='applicationLogsDialog';dialog.innerHTML='<div class="modal-title"><div><h2>Runtime logs</h2><small id="applicationLogsSubtitle"></small></div><button class="icon" data-close>×</button></div><div id="applicationLogsContent"></div>';document.body.appendChild(dialog);dialog.querySelector('[data-close]').onclick=()=>dialog.close();return dialog}
async function deployExisting(id){const item=await api(`/api/deployments/${encodeURIComponent(id)}`);const action=item.state==='RUNNING'?'restart':'start';if(!confirm(`No new configuration is pending. Deploy the existing ${item.packageId} configuration now?`))return;try{await api(`/api/deployments/${encodeURIComponent(id)}/${action}`,{method:'POST'});toast('Existing application configuration deployed');await load()}catch(error){toast(error.message,true);await load()}}
async function deleteDeployment(id){const item=await api(`/api/deployments/${encodeURIComponent(id)}`);if(item.state!=='UNDEPLOYED'){toast('Undeploy the application before deleting it',true);return}if(!confirm(`Permanently delete deployment ${item.application}?`))return;try{await api(`/api/deployments/${encodeURIComponent(id)}`,{method:'DELETE'});toast('Deployment deleted');await load()}catch(error){toast(error.message,true)}}
async function revertDeployment(id,revision){if(!revision)return;if(!confirm(`Revert this application to revision ${revision}?`))return;try{await api(`/api/deployments/${encodeURIComponent(id)}/revert`,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({revision})});toast(`Reverted to revision ${revision}`);await load();await details(id)}catch(error){toast(error.message,true)}}
async function viewLogs(id){const dialog=ensureLogsDialog(),content=q('#applicationLogsContent');content.innerHTML='<p class="notice">Loading runtime logs…</p>';dialog.showModal();try{const [item,logs]=await Promise.all([api(`/api/deployments/${encodeURIComponent(id)}`),api(`/api/deployments/${encodeURIComponent(id)}/logs?lines=2000`)]);q('#applicationLogsSubtitle').textContent=`${item.application} · ${item.packageId} · ${item.environment}`;content.innerHTML=logs.map(x=>`<section class="log-instance"><b>${esc(x.instanceId||'runtime')}</b><pre>${esc((x.lines||[]).join('\\n'))||'No log output.'}</pre></section>`).join('')||'<div class="empty">No runtime logs are available.</div>'}catch(error){content.innerHTML=`<p class="notice failure">${esc(error.message)}</p>`}}
async function applicationActions(id){try{const item=await api(`/api/deployments/${encodeURIComponent(id)}`),revisions=await api(`/api/revisions/deployment/${encodeURIComponent(id)}`),dialog=ensureActionDialog();q('#applicationActionsTitle').textContent=item.application;q('#applicationActionsSubtitle').textContent=`${item.packageId} · ${planeName(item.dataPlaneId||item.machine)} · ${item.namespace||'default'}`;q('#applicationActionsContent').innerHTML=`<div class="action-command-grid"><button class="primary" onclick="deployExisting('${esc(id)}')">Deploy current configuration</button><button onclick="details('${esc(id)}');q('#applicationActionsDialog').close()">Config</button><button onclick="viewLogs('${esc(id)}');q('#applicationActionsDialog').close()">View logs</button><button onclick="details('${esc(id)}');q('#applicationActionsDialog').close()">History</button>${item.state==='RUNNING'?`<button onclick="lifecycle('${esc(id)}','stop');q('#applicationActionsDialog').close()">Stop</button>`:`<button onclick="lifecycle('${esc(id)}','start');q('#applicationActionsDialog').close()">Start</button>`}<button class="danger" onclick="lifecycle('${esc(id)}','undeploy');q('#applicationActionsDialog').close()">Undeploy</button><button class="danger" ${item.state!=='UNDEPLOYED'?'disabled':''} onclick="deleteDeployment('${esc(id)}');q('#applicationActionsDialog').close()">Delete undeployed</button></div><h3>Revert deployment</h3><p class="notice">Choose an earlier recorded revision. Secret values are never exposed or restored by this operation.</p><div class="revert-row"><select id="revertRevision"><option value="">Select revision…</option>${revisions.map(x=>`<option value="${esc(x.revision)}">Revision ${esc(x.revision)} · ${esc(x.action)} · ${esc(fmt(x.time))}</option>`).join('')}</select><button onclick="revertDeployment('${esc(id)}',q('#revertRevision').value)">Revert</button></div>`;dialog.showModal()}catch(error){toast(error.message,true)}}
async function downloadBackup(id){const response=await fetch(`/api/deployments/${encodeURIComponent(id)}/backup`,{headers:controlPlaneKey?{'X-Admin-Key':controlPlaneKey}:{}});if(!response.ok){toast('Backup failed',true);return}const blob=await response.blob(),link=document.createElement('a');link.href=URL.createObjectURL(blob);link.download=`deployment-${id}-backup.zip`;link.click();setTimeout(()=>URL.revokeObjectURL(link.href),1000)}
async function instanceControl(deploymentId,instanceId,action){try{await api(`/api/deployments/${encodeURIComponent(deploymentId)}/instances/${encodeURIComponent(instanceId)}/${action}`,{method:'POST'});toast(`Instance ${action} requested`);await load();await details(deploymentId)}catch(error){toast(error.message,true)}}
function restoreBackup(id){const input=document.createElement('input');input.type='file';input.accept='.zip';input.onchange=async()=>{if(!input.files[0])return;const data=new FormData();data.append('file',input.files[0]);try{await api(`/api/deployments/${encodeURIComponent(id)}/restore`,{method:'POST',body:data});toast('Deployment backup restored');await load();await details(id)}catch(error){toast(error.message,true)}};input.click()}
async function compareDeployment(id){try{const value=await api(`/api/deployments/${encodeURIComponent(id)}/compare`),dialog=ensureActionDialog();q('#applicationActionsTitle').textContent='Deployment comparison';q('#applicationActionsSubtitle').textContent=`${id} · current versus latest recorded revision`;q('#applicationActionsContent').innerHTML=Object.keys(value.changes||{}).length?Object.entries(value.changes).map(([key,change])=>`<div class="asset-row"><b>${esc(key)}</b><span>${esc(JSON.stringify(change.from))}</span><span>→ ${esc(JSON.stringify(change.to))}</span></div>`).join(''):'<p class="notice success">No configuration changes detected.</p>';dialog.showModal()}catch(error){toast(error.message,true)}}
const originalDetails=details;details=async function(id){await originalDetails(id);const content=q('#detailsContent');if(!content)return;let toolbar=content.querySelector('.lifecycle-toolbar');if(!toolbar){toolbar=document.createElement('div');toolbar.className='actions lifecycle-toolbar';toolbar.innerHTML=`<button class="primary" onclick="deployExisting('${esc(id)}')">Deploy current</button><button onclick="viewLogs('${esc(id)}')">View logs</button><button onclick="compareDeployment('${esc(id)}')">Compare</button><button onclick="downloadBackup('${esc(id)}')">Backup</button><button onclick="restoreBackup('${esc(id)}')">Restore</button><button onclick="applicationActions('${esc(id)}')">All actions</button>`;content.prepend(toolbar)}try{const instances=await api(`/api/operator/process-instances?deploymentId=${encodeURIComponent(id)}`);if(instances.length&&!content.querySelector('.operator-instances')){const section=document.createElement('section');section.className='operator-instances';section.innerHTML=`<h3>Process instances</h3>${instances.map(instance=>`<div class="asset-row"><div><b>${esc(instance.id)}</b><small>${esc(instance.taskId)} · ${esc(instance.correlationId||'No correlation ID')}</small></div>${status(instance.status)}<span>${esc(instance.durationMs==null?'—':`${instance.durationMs} ms`)}</span><div class="actions"><button onclick="instanceControl('${esc(id)}','${esc(instance.id)}','suspend')">Suspend</button><button onclick="instanceControl('${esc(id)}','${esc(instance.id)}','resume')">Resume</button></div></div>`).join('')}`;content.appendChild(section)}}catch(error){toast(error.message,true)}};
const originalRenderApplications=renderApplications;renderApplications=function(){originalRenderApplications();document.querySelectorAll('#content .app-row').forEach(row=>{row.classList.add('interactive-row');const actionButton=row.querySelector('.actions button');const idMatch=actionButton?.getAttribute('onclick')?.match(/details\('([^']+)'\)/);if(!idMatch)return;const id=idMatch[1];row.addEventListener('dblclick',event=>{if(!event.target.closest('button'))details(id)});const actions=row.querySelector('.actions');const menu=document.createElement('button');menu.textContent='Actions';menu.onclick=()=>applicationActions(id);actions.appendChild(menu)})};
async function renderOperations(){noAction();q('#pageActions').innerHTML='<button class="primary" onclick="renderOperations()">Refresh operations</button>';q('#content').innerHTML=panel('Runtime topology','Data plane → capability → application → runtime instance', '<div class="notice">Loading runtime topology…</div>');try{const [tree,metrics,commands,alerts]=await Promise.all([api('/api/operator/runtime-tree'),api('/api/operator/metrics'),api('/api/operator/commands?limit=30'),api('/api/alerts')]);const topology=(tree.dataPlanes||[]).map(plane=>`<article class="card"><div class="card-head"><div><small>DATA PLANE</small><b>${esc(plane.name)}</b></div>${status(plane.status)}</div>${(plane.capabilities||[]).map(cap=>`<div class="environment"><b>${esc(cap.name)}</b><small>${esc(cap.namespace||'default')} · ${esc(cap.version||'')}</small>${(cap.applications||[]).map(app=>`<div class="principal"><div class="avatar">APP</div><div><b>${esc(app.application)}</b><small>${esc(app.environment)} · ${esc(app.state)}</small></div><span>${(app.instances||[]).map(instance=>`<em>${esc(instance.id)} · ${esc(instance.taskId)}</em>`).join(' ')||'No runtime instances'}</span></div>`).join('')||'<small>No applications</small>'}</div>`).join('')||'<div class="empty">No capabilities provisioned.</div>'}</article>`).join('')||'<div class="empty">No data planes available.</div>';const alertRows=(alerts||[]).map(alert=>`<div class="asset-row"><div><b>${esc(alert.name)}</b><small>${esc(alert.type)}</small></div>${status(alert.state)}<span>Value: ${esc(alert.value??'—')} / threshold ${esc(alert.threshold)}</span><time>${fmt(alert.evaluatedAt)}</time></div>`).join('')||'<div class="empty">No alert rules configured.</div>';const commandRows=(commands||[]).slice(0,20).map(item=>`<div class="timeline"><i></i><div><b>${esc(item.action)}</b><span>${esc(item.target)}</span><small>${esc(item.outcome)} · ${esc(item.detail||'')}</small></div><time>${fmt(item.time)}</time></div>`).join('')||'<div class="empty">No command history.</div>';q('#content').innerHTML=panel('Runtime topology','Data plane → capability → application → runtime instance',`<div class="cards">${topology}</div>`)+panel('Application metrics',`${metrics.instances||0} instances · ${metrics.successRate||0}% success rate`, `<div class="stats"><article><b>${metrics.running||0}</b><small>RUNNING</small></article><article><b>${metrics.completed||0}</b><small>COMPLETED</small></article><article><b>${metrics.failed||0}</b><small>FAILED</small></article><article><b>${metrics.requests||0}</b><small>CONTROL PLANE REQUESTS</small></article></div>`)+panel('Alerts','Offline data planes, failed deployments, unhealthy applications, and resource thresholds',`<div class="asset-list">${alertRows}</div>`)+panel('Command history','Lifecycle and governance operations with outcomes',`<div class="timeline-list">${commandRows}</div>`)}catch(error){q('#content').innerHTML=panel('Operations unavailable','The operator data could not be loaded',`<p class="notice failure">${esc(error.message)}</p>`)}}
pageMeta.operations=['OPERATE','Operations','Runtime topology, process instances, metrics, alerts, and command history.'];const baseRender=render;render=function(){if(state.view==='operations')return renderOperations();return baseRender()};
function enhanceApplications(){if(state.view!=='applications')return;const actions=q('#pageActions'),search=q('#applicationSearch');if(!actions||!search||q('#applicationStateFilter'))return;const filter=document.createElement('select');filter.id='applicationStateFilter';filter.title='Filter application state';filter.innerHTML='<option value="ALL">All states</option><option value="RUNNING">Running</option><option value="DEPLOYED">Deployed</option><option value="STOPPED">Stopped</option><option value="FAILED">Failed</option>';actions.insertBefore(filter,q('#assetTeamPicker'));const refresh=document.createElement('button');refresh.id='refreshApplications';refresh.textContent='Refresh';refresh.onclick=()=>load();actions.appendChild(refresh);const apply=()=>{const term=search.value.trim().toLowerCase(),selected=filter.value;document.querySelectorAll('#content .app-row.searchable').forEach(row=>{row.hidden=!!(term&&!row.dataset.search.includes(term))||!!(selected!=='ALL'&&!row.dataset.search.includes(selected.toLowerCase()))})};search.oninput=apply;filter.onchange=apply;apply()}
const enhancedRenderApplications=renderApplications;renderApplications=function(){enhancedRenderApplications();enhanceApplications()};
async function bulkDeploymentAction(action){const ids=[...document.querySelectorAll('#content .app-row input[data-deployment-id]:checked')].map(x=>x.dataset.deploymentId);if(!ids.length)return toast('Select at least one deployment',true);if(!confirm(`${action} ${ids.length} selected deployment(s)?`))return;try{await api('/api/deployments/bulk',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({action,deploymentIds:ids})});toast(`Bulk ${action} requested`);await load()}catch(error){toast(error.message,true)}}
const baseEnhanceApplications=enhanceApplications;enhanceApplications=function(){baseEnhanceApplications();if(state.view!=='applications'||q('#bulkDeploymentActions'))return;const actions=q('#pageActions'),bulk=document.createElement('span');bulk.id='bulkDeploymentActions';bulk.innerHTML='<button onclick="bulkDeploymentAction(\'start\')">Start selected</button><button onclick="bulkDeploymentAction(\'stop\')">Stop selected</button><button class="danger" onclick="bulkDeploymentAction(\'undeploy\')">Undeploy selected</button>';actions.appendChild(bulk);document.querySelectorAll('#content .app-row').forEach(row=>{const button=row.querySelector('.actions button'),match=button?.getAttribute('onclick')?.match(/details\('([^']+)'\)/);if(!match||row.querySelector('[data-deployment-id]'))return;const checkbox=document.createElement('input');checkbox.type='checkbox';checkbox.dataset.deploymentId=match[1];checkbox.title='Select deployment';row.prepend(checkbox)})};
let telemetryRefreshTimer=null;
function telemetryModal(title,subtitle,body){q('#detailsTitle').textContent=title;q('#detailsSubtitle').textContent=subtitle;q('#detailsContent').innerHTML=body;q('#detailsDialog').showModal()}
async function telemetryDetail(kind){try{const o=await api('/api/observability'),instances=kind==='instances'?await api('/api/operator/process-instances'):[];if(kind==='errors'){const errors=o.requests?.recentErrors||[];const reason=statusCode=>statusCode===401?'Credential missing or invalid':statusCode===404?'Requested API route was not found':statusCode===409?'Operation conflicts with current runtime state':statusCode>=500?'Control Plane or runtime service failed':'Request validation or access was rejected';telemetryModal('Control Plane errors',`${o.summary?.errorCount||0} failed requests · ${o.summary?.errorRate||0}% of requests`,errors.length?`<div class="asset-list">${errors.slice().reverse().map(x=>`<div class="asset-row"><div><b>${esc(x.method)} ${esc(x.path)}</b><small>${esc(reason(x.status))}</small></div>${status(`HTTP ${x.status}`)}<time>${fmt(x.time)}</time></div>`).join('')}</div>`:'<div class="empty">No failed Control Plane requests have been recorded since this process started.</div>')}else if(kind==='instances'){telemetryModal('Running runtime instances',`${instances.length} instance record(s) currently visible`,instances.length?`<div class="asset-list">${instances.map(x=>`<div class="asset-row"><div><b>${esc(x.application)}</b><small>${esc(x.taskId)} · ${esc(x.id)}</small></div>${status(x.status)}<span>${esc(x.correlationId||'No correlation ID')}</span><span>${esc(x.dataPlaneId)}</span></div>`).join('')}</div>`:'<div class="empty">No runtime instances are currently reported.</div>')}else if(kind==='requests'){const routes=Object.entries(o.requests?.routes||{}).sort((a,b)=>b[1]-a[1]);telemetryModal('Control Plane requests',`${o.summary?.requestCount||0} requests since this Control Plane process started`,routes.length?`<div class="asset-list">${routes.map(([route,count])=>`<div class="asset-row"><div><b>${esc(route)}</b><small>Control Plane API activity</small></div><b>${count}</b></div>`).join('')}</div>`:'<div class="empty">No request activity is available for this account.</div>')}else{telemetryModal('Deployed projects',`${(o.applications||[]).length} deployment(s) visible to this credential`,(o.applications||[]).map(x=>`<div class="asset-row"><div><b>${esc(x.name)}</b><small>${esc(x.namespace)} · ${esc(x.dataPlaneId)}</small></div>${status(x.state)}<span>${x.instances} instance(s)</span></div>`).join('')||'<div class="empty">No deployed projects are visible.</div>')}}catch(error){toast(error.message,true)}}
function bindTelemetryCards(){const cards=[...q('#stats').querySelectorAll('article')];[['requests','Control Plane request count'],['errors','Why requests failed'],['instances','Runtime worker details'],['projects','Deployed project details']].forEach(([kind,label],index)=>{const card=cards[index];if(!card)return;card.classList.add('metric-action');card.title=label;card.onclick=()=>telemetryDetail(kind);card.onkeydown=e=>{if(e.key==='Enter'||e.key===' ')telemetryDetail(kind)};card.tabIndex=0})}
function configureTelemetryRefresh(){if(telemetryRefreshTimer){clearInterval(telemetryRefreshTimer);telemetryRefreshTimer=null}if(!state.telemetryStatic)telemetryRefreshTimer=setInterval(()=>{if(state.view==='observability')load()},10000)}
renderObservability=function(){const o=state.observability||{},s=o.summary||{},planes=o.dataPlanes||[];setStats([metric(s.requestCount||0,'REQUEST COUNT'),metric(`${s.errorRate||0}%`,'ERROR RATE'),metric(s.runningInstances||0,'RUNNING INSTANCES'),metric(s.applications||0,'APPLICATIONS')]);q('#pageActions').innerHTML=`<button onclick="load()">Refresh now</button><label class="realtime-toggle"><input id="telemetryRealtime" type="checkbox" ${state.telemetryStatic?'':'checked'}> Live refresh <small>${state.telemetryStatic?'static snapshot':'every 10 seconds'}</small></label>`;q('#telemetryRealtime').onchange=e=>{state.telemetryStatic=!e.target.checked;configureTelemetryRefresh();renderObservability()};bindTelemetryCards();const hosts=planes.map(x=>{const t=x.telemetry?.system||x,available=t.memoryTotalBytes!=null;return `<button class="host-telemetry telemetry-action" onclick="dataPlaneDetails('${esc(x.id)}')"><div class="card-head"><div><small>${esc(x.id)}</small><b>${esc(x.name)}</b></div>${status(x.status)}</div><div class="gauge-grid">${gauge('CPU',t.cpuPercent,`Load ${t.loadAverage??'—'}`)}${gauge('RAM',t.memoryPercent,available?`${bytes(t.memoryUsedBytes)} / ${bytes(t.memoryTotalBytes)}`:'Agent has not reported memory yet','green')}${gauge('Disk',t.diskPercent,t.diskFreeBytes!=null?`${bytes(t.diskFreeBytes)} free`:'Agent has not reported disk yet','amber')}</div><div class="host-footer"><span>${t.processCount??'—'} workers</span><span>Click to inspect machine · ${fmt(x.lastHeartbeat)}</span></div></button>`}).join('')||'<div class="empty">No agent telemetry yet. Start the remote data-plane agent and wait for its next heartbeat.</div>';const errors=(o.requests?.recentErrors||[]).length;q('#content').innerHTML=panel('Host telemetry','Click a machine for its agent connection, namespaces, and runtime configuration.',`<div class="host-telemetry-grid">${hosts}</div>`)+panel('Execution analytics','Task and activity outcomes collected from runtime JSON logs on each data plane.',`<div class="execution-columns"><div><h3>Tasks</h3>${executionRows(state.operatorMetrics?.tasks,'No completed task events have been reported yet.')}</div><div><h3>Activities</h3>${executionRows(state.operatorMetrics?.activities,'No completed activity events have been reported yet.')}</div></div>`)+panel('Request health',errors?`${errors} failed request(s) are available for inspection.`:'No failed requests recorded.',`<div class="bars">${Object.entries(o.requests?.routes||{}).sort((a,b)=>b[1]-a[1]).slice(0,10).map(([name,count])=>`<button class="bar route-action" onclick="telemetryDetail('errors')"><span>${esc(name)}</span><i style="--value:${Math.min(100,Number(count))}%"></i><b>${count}</b></button>`).join('')||'<div class="empty">No request telemetry is available for this account.</div>'}</div>`)};
const enhancedDataPlaneDetails=dataPlaneDetails;dataPlaneDetails=async function(id){await enhancedDataPlaneDetails(id);const content=q('#detailsContent'),plane=state.dataPlanes.find(x=>x.id===id),t=plane?.telemetry?.system||plane;if(!content||!plane)return;content.insertAdjacentHTML('afterbegin',`<div class="machine-inspect-actions"><button class="primary" onclick="telemetryDetail('instances')">View runtime instances</button><button onclick="state.view='observability';renderObservability();q('#detailsDialog').close()">Open live telemetry</button></div><div class="machine-inline-stats"><span>CPU <b>${t?.cpuPercent??'—'}%</b></span><span>RAM <b>${t?.memoryPercent??'—'}%</b></span><span>Disk <b>${t?.diskPercent??'—'}%</b></span><span>Load <b>${t?.loadAverage??'—'}</b></span></div>`)};
